const { validatePrTitle: validate } = require("./validatePrTitle");
const { ERRORS, NO_CHANGELOG, SCOPES } = require("./constants");
const displayNamesModule = require("./getAllNodesDisplayNames");
const { TYPES } = require("./constants");
const {
  ALL_NODES_DISPLAY_NAMES_FOR_TESTING_ONLY,
} = require("./testDisplayNames");

jest.mock("./getAllNodesDisplayNames");

jest
  .spyOn(displayNamesModule, "getAllNodesDisplayNames")
  .mockReturnValue(ALL_NODES_DISPLAY_NAMES_FOR_TESTING_ONLY);

describe("schema", () => {
  test("Validation should fail for conventional schema mismatch", () => {
    ["feat(core):", "feat(core)", "feat(core) implement feature"].forEach(
      async (title) => {
        const issues = await validate(title);
        expect(issues)
          .toHaveLength(1)
          .toContain(ERRORS.CONVENTIONAL_SCHEMA_MISMATCH);
      },
    );
  });

  test("Validation should fail for valid ticket number in schema", () => {
    [
      "feat(Mattermost node): Add new resource n8n-1234",
      "n8n-1234 feat(Mattermost node): Add new resource",
      "feat(Mattermost node) n8n-1234: Add new resource",
    ].forEach(async (title) => {
      const issues = await validate(title);
      expect(issues).toHaveLength(1).toContain(ERRORS.TICKET_NUMBER_PRESENT);
    });
  });

  test("Validation should fail for PR number in schema", () => {
    [
      "feat(Mattermost node): Add new resource #12345",
      "feat(Mattermost node): Add new #123445 resource",
      "feat(Mattermost node): #12345 Add new resource",
    ].forEach(async (title) => {
      const issues = await validate(title);
      expect(issues).toHaveLength(1).toContain(ERRORS.PR_NUMBER_PRESENT);
    });
  });
});

describe("type", () => {
  test("Validation should pass for valid type", () => {
    TYPES.forEach(async (type) => {
      const issues = await validate(`${type}(core): Implement feature`);
      expect(issues).toHaveLength(0);
    });
  });

  test("Validation should fail for invalid type", async () => {
    const issues = await validate("wrong(core): Implement feature");
    expect(issues).toHaveLength(1).toContain(ERRORS.INVALID_TYPE);
  });
});

describe("scope", () => {
  test("Validation should pass for valid title with scope", async () => {
    const issues = await validate("feat(core): Implement feature");
    expect(issues).toHaveLength(0);
  });

  test("Validation should pass for title with multiple valid scopes", async () => {
    const issues = await validate("feat(core, editor): Implement feature");
    expect(issues).toHaveLength(0);
  });

  test("Validation should fail for title with valid scope and invalid scope", async () => {
    const issues = await validate("feat(core, wrong): Implement feature");
    expect(issues).toHaveLength(1).toContain(ERRORS.INVALID_SCOPE);
  });

  test("Validation should fail for title with multiple invalid scopes", async () => {
    const issues = await validate("feat(wrong1, wrong2): Implement feature");
    expect(issues).toHaveLength(2).toContain(ERRORS.INVALID_SCOPE);
  });

  test("Validation should fail for title with misdelimited valid scopes", async () => {
    expect(await validate("feat(core,editor): Implement feature"))
      .toHaveLength(1)
      .toContain(ERRORS.MISSING_WHITESPACE_AFTER_COMMA);
  });

  test("Validation should pass for valid title without scope", async () => {
    const issues = await validate("feat: Implement feature");
    expect(issues).toHaveLength(0);
  });

  test("Validation should fail for miscased node suffix", async () => {
    const issues = await validate("feat(Mattermost node): Add new resource");
    expect(issues).toHaveLength(1).toContain(ERRORS.INVALID_SCOPE);
  });

  test("Validation should fail for misspelled node scope", async () => {
    let issues = await validate("feat(Mattermos Node): Change default value");
    expect(issues)
      .toHaveLength(1)
      .toContain(ERRORS.INVALID_SCOPE + ". Did you mean `Mattermost Node`?");

    issues = await validate("feat(Gmai Trigger Node): Change default value");
    expect(issues)
      .toHaveLength(1)
      .toContain(ERRORS.INVALID_SCOPE + ". Did you mean `Gmail Trigger Node`?");
  });

  test.each(SCOPES)(
    'Validation should pass for valid scope "%s"',
    async (scope) => {
      const issues = await validate(`feat(${scope}): Implement feature`);
      expect(issues).toHaveLength(0);
    },
  );
});

describe("subject", () => {
  test("Validation should fail for lowercase initial in subject", async () => {
    const issues = await validate("feat(core): implement feature");
    expect(issues)
      .toHaveLength(1)
      .toContain(ERRORS.LOWERCASE_INITIAL_IN_SUBJECT);
  });

  test("Validation should fail for final period in subject", async () => {
    const issues = await validate("feat(core): Implement feature.");
    expect(issues).toHaveLength(1).toContain(ERRORS.FINAL_PERIOD_IN_SUBJECT);
  });

  test("Validation should pass for present-tense verb", async () => {
    const issues = await validate("feat(editor): Update something");
    expect(issues).toHaveLength(0);
  });

  test("Validation should fail for non-present-tense verb", async () => {
    [
      "feat(Mattermost Node): Added new resource",
      "feat(Mattermost Node): Created new resource",
    ].forEach(async (title) => {
      const issues = await validate(title);
      expect(issues)
        .toHaveLength(1)
        .toContain(ERRORS.NO_PRESENT_TENSE_IN_SUBJECT);
    });
  });

  test("Validation should pass for breaking-change indicator `!`", async () => {
    const issues = await validate("feat(Oura Node)!: Change default value");
    expect(issues).toHaveLength(0);
  });

  test(`Validation should pass for \`${NO_CHANGELOG}\` in final position`, async () => {
    const issues = await validate("docs(Oura Node): Fix typo (no-changelog)");
    expect(issues).toHaveLength(0);
  });

  test(`Validation should fail for \`${NO_CHANGELOG}\` not in final position`, () => {
    [
      "docs(Oura Node): Fix (no-changelog) typo",
      "docs(Oura Node): Fix typo(no-changelog) ",
      "docs(Oura Node): Fix (no-changelog) typo",
    ].forEach(async (title) => {
      const issues = await validate(title);
      expect(issues)
        .toHaveLength(1)
        .toContain(ERRORS.SKIP_CHANGELOG_NOT_IN_FINAL_POSITION);
    });
  });

  test("Validation should fail for initial paren in subject", () => {
    [
      "feat(Mattermost Node): (Add new resource",
      "feat(Mattermost Node): (Add new resource)",
    ].forEach(async (title) => {
      const issues = await validate(title);
      expect(issues).toHaveLength(1).toContain(ERRORS.INITIAL_PAREN_IN_SUBJECT);
    });
  });
});

const core = require("@actions/core");
const github = require("@actions/github");

const { validatePrTitle } = require("./src/validatePrTitle");

async function run() {
  try {
    const contextPullRequest = github.context.payload.pull_request;

    if (!contextPullRequest) {
      throw new Error(
        "This action may only be triggered by `pull_request` events. Set `pull_request` in the `on` section in your workflow.",
      );
    }

    const owner = contextPullRequest.base.user.login;
    const repo = contextPullRequest.base.repo.name;

    const client = github.getOctokit(process.env.GITHUB_TOKEN, {
      baseUrl: "https://api.github.com",
    });

    // When user updates a PR title, context PR data is outdated,
    // so fetch the latest PR data via GitHub REST API.
    const { data: pullRequest } = await client.rest.pulls.get({
      owner,
      repo,
      pull_number: contextPullRequest.number,
    });

    const issues = await validatePrTitle(pullRequest.title);

    if (issues.length > 0) {
      console.error("PR title failed validation");
      core.setOutput(
        "validation_issues",
        issues.map((issue) => `- ${issue}`).join("\n"),
      );

      throw new Error(issues);
    }

    console.info("PR title validated successfully");
  } catch (error) {
    console.error("validate-n8n-pull-request-title failed to run");
    core.setFailed(error.message);
  }
}

run();

const { closest } = require("fastest-levenshtein");
const { getAllNodesDisplayNames } = require("./getAllNodesDisplayNames");
const { TYPES, SCOPES, NO_CHANGELOG, ERRORS, REGEXES } = require("./constants");

/**
 * Validate that a pull request title matches n8n's version of the Conventional Commits spec.
 *
 * See: https://www.notion.so/n8n/Release-Process-fce65faea3d5403a85210f7e7a60d0f8
 */
async function validatePrTitle(title) {
  const match = title.match(REGEXES.CONVENTIONAL_SCHEMA);

  // general validation

  if (!match) return [ERRORS.CONVENTIONAL_SCHEMA_MISMATCH];

  if (containsTicketNumber(title)) return [ERRORS.TICKET_NUMBER_PRESENT];

  if (containsPrNumber(title)) return [ERRORS.PR_NUMBER_PRESENT];

  const issues = [];

  // type validation

  if (!match?.groups?.type) {
    issues.push(ERRORS.TYPE_NOT_FOUND);
  }

  const { type } = match.groups;

  if (isInvalidType(type)) {
    issues.push(ERRORS.INVALID_TYPE);
  }

  // scope validation

  const { scope } = match.groups;

  if (scope) {
    if (/,\S/.test(scope)) {
      issues.push(ERRORS.MISSING_WHITESPACE_AFTER_COMMA);
    } else {
      const scopeIssues = await Promise.all(
        scope.split(", ").map(getScopeIssue),
      );
      issues.push(...scopeIssues.filter((scopeIssue) => scopeIssue !== null));
    }
  }

  // subject validation

  const { subject } = match.groups;

  if (startsWithLowerCase(subject)) {
    issues.push(ERRORS.LOWERCASE_INITIAL_IN_SUBJECT);
  }

  if (subject.startsWith("(")) {
    issues.push(ERRORS.INITIAL_PAREN_IN_SUBJECT);
  }

  if (endsWithPeriod(subject)) {
    issues.push(ERRORS.FINAL_PERIOD_IN_SUBJECT);
  }

  if (doesNotUsePresentTense(subject)) {
    issues.push(ERRORS.NO_PRESENT_TENSE_IN_SUBJECT);
  }

  if (hasSkipChangelog(subject) && skipChangelogIsNotInFinalPosition(subject)) {
    issues.push(ERRORS.SKIP_CHANGELOG_NOT_IN_FINAL_POSITION);
  }

  return issues;
}

/**
 * Helpers
 */

const containsPrNumber = (str) => REGEXES.PR_NUMBER.test(str);

const isInvalidType = (str) => !TYPES.includes(str);

const isInvalidNodeScope = (str, allNodesDisplayNames) =>
  !allNodesDisplayNames.some((name) => str.startsWith(name));

const getScopeIssue = async (scope) => {
  if (scope.endsWith(" Node")) {
    const names = await getAllNodesDisplayNames();

    if (names.length === 0) {
      console.log("Failed to find all nodes display names. Skipping check...");
      return null;
    }

    if (isInvalidNodeScope(scope, names)) {
      const closest = getClosestMatch(scope, names);
      const supplement = `. Did you mean \`${closest} Node\`?`;

      return ERRORS.INVALID_SCOPE + supplement;
    }
  } else if (!SCOPES.includes(scope)) {
    return ERRORS.INVALID_SCOPE;
  }

  return null;
};

const startsWithLowerCase = (str) => /^[a-z]/.test(str);

const endsWithPeriod = (str) => /\.$/.test(str);

const containsTicketNumber = (str) => REGEXES.TICKET.test(str);

const doesNotUsePresentTense = (str) => {
  const verb = str.split(" ").shift();

  return verb.endsWith("ed"); // naive check
};

const hasSkipChangelog = (str) => str.includes(NO_CHANGELOG);

const skipChangelogIsNotInFinalPosition = (str) => {
  const suffixPattern = [" ", escapeForRegex(NO_CHANGELOG), "$"].join("");

  return !new RegExp(suffixPattern).test(str);
};

const escapeForRegex = (str) => str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

const getClosestMatch = (str, names) =>
  closest(str.split(" Node").shift(), names);

module.exports = { validatePrTitle };

const TYPES = [
  "feat",
  "fix",
  "perf",
  "test",
  "docs",
  "refactor",
  "build",
  "ci",
  "chore",
];

const SCOPES = ["API", "core", "editor", "benchmark", "ai-builder", "engine"];

const displayTypes = TYPES.map((type) => `\`${type}\``).join(", ");
const displayScopes = SCOPES.map((type) => `\`${type}\``).join(", ");

const NO_CHANGELOG = "(no-changelog)";

const ERRORS = {
  CONVENTIONAL_SCHEMA_MISMATCH: [
    "PR title does not match PR title convention: type: subject or type(scope): subject",
    `For \`type\`, use \`type:\` or \`type(scope):\`, where \`type\` is one of ${displayTypes}`,
    `If present, \`scope\` must be one of ${displayScopes} or \`<displayName> Node\``,
    "For the subject, mind the whitespace, start with uppercase and omit final period",
  ].join(". "),
  TICKET_NUMBER_PRESENT: "PR title must not contain a ticket number",
  TYPE_NOT_FOUND: `Failed to find \`type\` in PR title. Expected one of ${displayTypes}`,
  INVALID_TYPE: `Unknown \`type\` in PR title. Expected one of ${displayTypes}`,
  INVALID_SCOPE: `Unknown \`scope\` in PR title. Expected one of ${displayScopes} or \`<displayName> Node\``,
  LOWERCASE_INITIAL_IN_SUBJECT: "First char of subject must be uppercase",
  FINAL_PERIOD_IN_SUBJECT: "Subject must not end with a period",
  NO_PRESENT_TENSE_IN_SUBJECT: "Subject must use present tense",
  SKIP_CHANGELOG_NOT_IN_FINAL_POSITION: `\`${NO_CHANGELOG}\` must be located at the end of the subject`,
  MISSING_WHITESPACE_AFTER_COMMA:
    "Missing whitespace after comma to separate multiple scopes",
  INITIAL_PAREN_IN_SUBJECT: "Subject must not start with parens",
  PR_NUMBER_PRESENT: "Title must not include pull request number",
};

const REGEXES = {
  CONVENTIONAL_SCHEMA: /(?<type>\w+)(\((?<scope>.*)\))?!?: (?<subject>.*)/,
  TICKET: /n8n-\d{3,5}/i,
  PR_NUMBER: /#\d{5,7}/,
};

module.exports = {
  TYPES,
  SCOPES,
  NO_CHANGELOG,
  ERRORS,
  REGEXES,
};

const { exec: callbackExec } = require("child_process");
const { promisify } = require("util");
const exec = promisify(callbackExec);

/**
 * @returns { Promise<string[]> } e.g. ["Action Network", "Active Campaign", etc.]
 */
async function getAllNodesDisplayNames() {
  try {
    await exec(
      "npm i typescript@5.3 @types/node@18.16 fast-glob; npm i -g ts-node@10.9",
    );
    await exec(`cp "${__dirname}/../src/parser.ts" parser.ts`);
    const result = await exec("ts-node parser.ts");
    return JSON.parse(result.stdout);
  } catch (error) {
    console.error("Failed to generate list of node display names");
    console.error(error);
  }
}

module.exports = {
  getAllNodesDisplayNames,
};

import path from "path";
import { readFileSync } from "fs";
import glob from "fast-glob";
import ts from "typescript";

const NODES_DIR = path.resolve("packages", "nodes-base", "nodes");
const LANGCHAIN_NODES_DIR = path.resolve("packages", "@n8n", "nodes-langchain", "nodes");

async function getDisplayNames() {
  const [nodeFilepaths, versionDescriptionFilepaths, lcNodeFilepaths, lcVersionDescriptionFilepaths] = await Promise.all([
    glob(path.resolve(NODES_DIR, "**", "*.node.ts")),
    glob(path.resolve(NODES_DIR, "**", "versionDescription.ts")),
    glob(path.resolve(LANGCHAIN_NODES_DIR, "**", "*.node.ts")),
    glob(path.resolve(LANGCHAIN_NODES_DIR, "**", "versionDescription.ts")),
  ]);

  const nodeFiles = [...nodeFilepaths, ...lcNodeFilepaths].reduce<string[]>((acc, cur) => {
    let displayName = fromMajorityNodeFile(cur);

    if (!displayName) {
      displayName = fromBaseNodeFileForVersioning(cur);
    }

    return displayName ? [...acc, displayName] : acc;
  }, []);

  const versionDescriptionFiles = [...versionDescriptionFilepaths, ...lcVersionDescriptionFilepaths].reduce<string[]>(
    (acc, cur) => {
      const displayName = fromVersionDescription(cur);

      return displayName ? [...acc, displayName] : acc;
    },
    [],
  );

  const allDisplayNames = [...nodeFiles, ...versionDescriptionFiles];

  // remove duplicates occurring from nodes \`displayName\` being both in
  // base file for versioning and in each of a node's version files

  return [...new Set(allDisplayNames)].sort();
}

/**
 * Get \`displayName\` from \`versionDescription\` object in \`versionDescription.ts\` file,
 * e.g. BambooHR, Mattermost, SyncroMSP
 */
function fromVersionDescription(filename: string): string | null {
  const sourceFile = makeSourceFile(filename);

  const varStatement = sourceFile.statements.find(isVariableStatement);

  if (!varStatement) return null;

  const versionDescriptionDeclaration =
    varStatement.declarationList.declarations.find(
      (d) => isIdentifier(d.name) && d.name.text === "versionDescription",
    );

  if (!versionDescriptionDeclaration?.initializer) return null;

  if (!isObjectLiteralExpression(versionDescriptionDeclaration.initializer))
    return null;

  const { initializer } = versionDescriptionDeclaration;

  const displayNamePropertyAssignment = initializer.properties.find(
    (p): p is ts.PropertyAssignment & { initializer: { text: string } } =>
      isPropertyAssignment(p) &&
      isIdentifier(p.name) &&
      p.name.text === "displayName" &&
      isStringLiteral(p.initializer),
  );

  if (!displayNamePropertyAssignment) return null;

  return displayNamePropertyAssignment.initializer.text;
}

/**
 * Get \`displayName\` from \`description\` field in class in \`*.node.ts\` file,
 * i.e. the majority of node files.
 */
function fromMajorityNodeFile(filename: string): string | null {
  const sourceFile = makeSourceFile(filename);

  const classDeclaration = sourceFile.statements.find(isClassDeclaration);

  if (!classDeclaration) return null;

  const descriptionMember = classDeclaration.members.find(
    (
      m,
    ): m is ts.PropertyDeclaration & {
      initializer: ts.ObjectLiteralExpression;
    } =>
      isPropertyDeclaration(m) &&
      isIdentifier(m.name) &&
      "description" === m.name.text &&
      m.initializer !== undefined &&
      isObjectLiteralExpression(m.initializer),
  );

  if (!descriptionMember) return null;

  const propertyAssignment = descriptionMember.initializer.properties.find(
    (p): p is ts.PropertyAssignment & { initializer: { text: string } } =>
      isPropertyAssignment(p) &&
      isIdentifier(p.name) &&
      p.name.text === "displayName" &&
      isStringLiteral(p.initializer),
  );

  if (!propertyAssignment) return null;

  return propertyAssignment.initializer.text;
}

/**
 * Get \`displayName\` from base \`*.node.ts\` file for versioning, where
 * \`displayName\` is in \`baseDescription\` inside a class constructor,
 * e.g. Notion (Beta), Merge, HTTP Request, SyncroMSP, Gmail, Mattermost
 */
function fromBaseNodeFileForVersioning(filename: string): string | null {
  const sourceFile = makeSourceFile(filename);

  const classDeclaration = sourceFile.statements.find(isClassDeclaration);

  if (!classDeclaration) return null;

  // unclear how to type this - members[i].constructor.body.statements
  const constructor = classDeclaration.members.find(
    (m) =>
      m.kind === ts.SyntaxKind.Constructor &&
      // @ts-ignore
      Array.isArray(m.body.statements),
  ) as { body?: { statements?: ts.Node[] } } | undefined;

  if (!constructor?.body?.statements) return null;

  const varStatement = constructor.body.statements.find(isVariableStatement);

  if (!varStatement) return null;

  const firstDeclaration = varStatement.declarationList.declarations[0];

  if (
    !firstDeclaration?.initializer ||
    !isObjectLiteralExpression(firstDeclaration.initializer)
  ) {
    return null;
  }

  const propertyAssignment = firstDeclaration.initializer.properties.find(
    (p): p is ts.PropertyAssignment & { initializer: { text: string } } =>
      isPropertyAssignment(p) &&
      isIdentifier(p.name) &&
      p.name.text === "displayName" &&
      isStringLiteral(p.initializer),
  );

  if (!propertyAssignment) return null;

  return propertyAssignment.initializer.text;
}

/**
 * Helpers
 */

function makeSourceFile(filename: string) {
  return ts.createSourceFile(
    filename,
    readFileSync(filename).toString(),
    ts.ScriptTarget.ES2022,
  );
}

function isVariableStatement(node: ts.Node): node is ts.VariableStatement {
  return node.kind === ts.SyntaxKind.VariableStatement;
}

function isIdentifier(statement: ts.Node): statement is ts.Identifier {
  return statement.kind === ts.SyntaxKind.Identifier;
}

function isObjectLiteralExpression(
  node: ts.Node,
): node is ts.ObjectLiteralExpression {
  return node.kind === ts.SyntaxKind.ObjectLiteralExpression;
}

function isPropertyAssignment(node: ts.Node): node is ts.PropertyAssignment {
  return node.kind === ts.SyntaxKind.PropertyAssignment;
}

function isPropertyDeclaration(node: ts.Node): node is ts.PropertyDeclaration {
  return node.kind === ts.SyntaxKind.PropertyDeclaration;
}

function isStringLiteral(node: ts.Node): node is ts.StringLiteral {
  return node.kind === ts.SyntaxKind.StringLiteral;
}

function isClassDeclaration(node: ts.Node): node is ts.ClassDeclaration {
  return node.kind === ts.SyntaxKind.ClassDeclaration;
}

getDisplayNames().then((result) =>
  console.log(JSON.stringify(result, null, 2)),
);
